const AFFIXES={gold:{label:'Ouro extra',suffix:'ouro',cap:75},xp:{label:'XP extra',suffix:'XP',cap:65},drop:{label:'Chance de drop extra',suffix:'drop',cap:45},crit:{label:'Crítico',suffix:'crítico',cap:35},critDamage:{label:'Dano crítico',suffix:'dano crítico',cap:90},lifesteal:{label:'Roubo de vida',suffix:'roubo de vida',cap:18},haste:{label:'Velocidade de ataque',suffix:'velocidade',cap:45},hp:{label:'Vida máxima',suffix:'HP',cap:60},mana:{label:'Mana máxima',suffix:'MP',cap:55},resist:{label:'Resistência',suffix:'resistência',cap:35},spell:{label:'Dano mágico',suffix:'magia',cap:65},move:{label:'Movimento',suffix:'movimento',cap:25},hpRegen:{label:'Regeneração de HP',suffix:'regeneração de HP',cap:150},mpRegen:{label:'Regeneração de MP',suffix:'regeneração de MP',cap:150},cooldown:{label:'Redução de recarga',suffix:'redução de recarga',cap:35},aoe:{label:'Dano em área',suffix:'dano em área',cap:60}};
const STAT_LABELS={attack:'Ataque físico',magic:'Poder mágico (%)',defense:'Defesa'};
function rollAffixes(rarity,level){const ranges={common:[0,1,2,4],uncommon:[1,1,3,6],rare:[1,2,5,10],veryrare:[2,2,7,13],epic:[2,3,10,17],legendary:[3,3,17,27]};const [min,max,low,high]=ranges[rarity];const count=randomInt(min,max);const names=Object.keys(AFFIXES);for(let j=names.length-1;j>0;j--){const k=randomInt(0,j);[names[j],names[k]]=[names[k],names[j]];}const result={};for(let i=0;i<count;i++){const key=names[i];result[key]=Math.min(AFFIXES[key].cap,randomInt(low,high)+Math.floor(level/8));}return result;}
function createItem(template,rarity,level,overrideValue){
 const tier=template.tier??Math.max(0,Math.floor(level/7));
 // Escala controlada por identidade da arma, zona e raridade; armas mágicas sempre em %.
 const raw=overrideValue??Math.max(1,Math.round(template.base*RARITIES[rarity].mult*(1+Math.max(0,tier)*.10)));
 const value=template.stat==='magic'?Math.min(95,Math.max(3,Math.round(raw*.52))):Math.max(1,raw);
 const requirements=template.stat==='magic'?{int:5+tier*2}:template.stat==='attack'?{str:5+tier*2,dex:5+Math.floor(tier/2)}:{con:5+tier};
 return {id:nextItemId++,refine:0,requirements,name:template.name,icon:template.icon,iconSrc:template.iconSrc,classId:template.classId,regionIndex:template.regionIndex,weaponKind:template.weaponKind||(template.name.startsWith('Arco ')?'bow':undefined),slot:template.slot,stat:template.stat,value,rarity,affixes:rollAffixes(rarity,Math.max(1,tier*4+1)),tier};
}
function itemRequirements(item){if(!item)return {};if(!item.requirements){const tier=item.tier??Math.max(0,Math.floor((item.level||1)/7));item.requirements=item.stat==='magic'?{int:5+tier*2}:item.stat==='attack'?{str:5+tier*2,dex:5+Math.floor(tier/2)}:{con:5+tier};}return item.requirements;}
function meetsRequirements(item){return Object.entries(itemRequirements(item)).every(([stat,value])=>hero[stat]>=value);}
function itemPower(item){const n=item.refine||0;return item.stat==='magic'?Math.min(180,Math.round(item.value*(1+n*.10)+n*1.5)):item.value+Math.round(item.value*.13*n+Math.pow(n,1.5)*2);}
